    if (kind === 'wo') { const n = f * (f - 1); return { q: tr(`Dua kartu diambil berturut-turut <b>tanpa pengembalian</b> dari 52 kartu remi. Peluang kedua kartu itu ${txt} adalah …`, `Two cards are drawn one after another <b>without replacement</b> from a 52-card deck. The probability that each of the two cards is ${txt} is …`), o: opts(frs(n, 2652), [frp(f * f, 2704), frp(f, 52), frp(2 * f, 52), frp(f - 1, 51), frp(n, 2704)], () => frs(R(1, 90), R(100, 2700))), exp: ST(tr(`Kartu pertama: ${f}/52. Kartu kedua (tersisa ${f - 1} dari 51): ${f - 1}/51.`, `First card: ${f}/52. Second card (${f - 1} left out of 51): ${f - 1}/51.`), `${fr(f, 52)} × ${fr(f - 1, 51)} = ${fr(n, 2652)} = <b>${frs(n, 2652)}</b>`) + TIP('Tanpa pengembalian: pembilang dan penyebut sama-sama berkurang satu pada pengambilan kedua.', 'Without replacement: both numerator and denominator drop by one on the second draw.') }; }
